<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Notice from '../components/Notice.vue'
import LoadingState from '../components/LoadingState.vue'
import MaterialPicker from './MaterialPicker.vue'
import InputPreview from './InputPreview.vue'
import type { Manifest } from './InputPreview.vue'
import ModelRecovery from './ModelRecovery.vue'
import { v2, writeV2, V2Error } from './api'
import { localDate } from './types'
import type { Page } from './types'
// 详情仅使用固定业务字段，模型原始响应不进入页面。
type Row = Record<string, any>
const route = useRoute(), router = useRouter(), id = computed(() => String(route.params.id || '')), isSprint = computed(() => route.path.startsWith('/sprints'))
const diagnostic = ref<Row | null>(null), sprint = ref<Row | null>(null), diagnostics = ref<Row[]>([]), sprints = ref<Row[]>([]), diagnosticCursor = ref<string | null>(null), sprintCursor = ref<string | null>(null)
const jdText = ref(''), jdMaterialIds = ref<string[]>([]), materialIds = ref<string[]>([]), observationIds = ref<string[]>([]), observations = ref<Row[]>([]), observationCursor = ref<string | null>(null), manifest = ref<Manifest | null>(null), replaceOf = ref('')
const selected = ref<string[]>([]), importance = reactive<Record<string, string>>({}), actionTypes = reactive<Record<string, string>>({}), purposes = reactive<Record<string, string>>({}), conditions = reactive<Record<string, string>>({})
const loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), recovery = ref<V2Error | null>(null)
const completionAction = ref(''), completionMaterialId = ref<string[]>([]), completionPreview = ref<Row | null>(null), coverage = ref(false), completionReason = ref(''), report = ref<Row | null>(null), reportSelection = ref(''), linkId = ref(String(route.query.trainingLinkId || ''))
const newerId = ref(''), diff = ref<Row | null>(null), history = ref<Row[]>([]), historyCursor = ref<string | null>(null), historical = ref<Row | null>(null), skipReasons = reactive<Record<string, string>>({})
const materialLabels: Record<string, string> = { MENTIONED: '材料已提及', NOT_MENTIONED: '材料未提及', INCOMPLETE: '材料不完整' }
const trainingLabels: Record<string, string> = { UNVERIFIED: '尚未验证', GAP: '练习暴露不足', SUPPORTED: '当前有局部支持证据', DISPUTED: '证据存在争议' }
const statusLabels: Record<string, string> = { RUNNING: '生成中', READY: '待确认', CONFIRMED: '已确认', FAILED: '生成失败', INTERRUPTED: '生成中断', TODO: '待办', IN_PROGRESS: '进行中', DONE: '用户确认完成', SKIPPED: '已跳过', ACTIVE: '活动清单', ARCHIVED: '已归档' }
const typeLabels: Record<string, string> = { MATERIAL_UPDATE: '补充材料', VERIFY_REQUIREMENT: '验证一个要求', RETRY_QUESTION: '重练一个问题' }
function fail(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，本页输入保留。'; recovery.value = e instanceof V2Error ? e : null }
try { const d = JSON.parse(sessionStorage.getItem('v2:jd-input') || 'null'); if (d) { jdText.value = d.jdText || ''; materialIds.value = d.materialIds || [] } } catch { /* 不读取未提交资料。 */ }
watch([jdText, materialIds], () => { try { sessionStorage.setItem('v2:jd-input', JSON.stringify({ jdText: jdText.value, materialIds: materialIds.value })) } catch { /* 本页输入保留。 */ } }, { deep: true })
async function loadObservations(more = false) { try { const p = await v2<Page<Row>>(`/available-training-observations?limit=20&cursor=${encodeURIComponent(more ? observationCursor.value || '' : '')}`); observations.value = more ? [...observations.value, ...p.items] : p.items; observationCursor.value = p.nextCursor } catch (e) { fail(e) } }
async function load() { loading.value = true; try { if (id.value) { if (isSprint.value) { sprint.value = await v2(`/sprints/${id.value}`); if (route.query.actionId) completionAction.value = String(route.query.actionId); if (linkId.value) await readReport() } else { diagnostic.value = await v2(`/jd-diagnostics/${id.value}`); selected.value = diagnostic.value!.requirements?.filter((r: Row) => diagnostic.value!.status === 'READY' || r.confirmed).map((r: Row) => r.id) || []; for (const r of diagnostic.value!.requirements || []) { importance[r.id] = r.importance; actionTypes[r.id] = 'VERIFY_REQUIREMENT'; purposes[r.id] = `核对“${r.jdQuote}”的证据`; conditions[r.id] = '完成相关练习，并确认所选报告结论实际覆盖此要求' } if (['FAILED', 'INTERRUPTED', 'RUNNING'].includes(diagnostic.value!.status)) recovery.value = Object.assign(new V2Error('诊断尚未完成'), { operationId: diagnostic.value!.operationId }) } } else { const [dp, sp] = await Promise.all([v2<Page<Row>>('/jd-diagnostics?limit=20'), v2<Page<Row>>('/sprints?limit=20')]); diagnostics.value = dp.items; diagnosticCursor.value = dp.nextCursor; sprints.value = sp.items; sprintCursor.value = sp.nextCursor; await loadObservations() } } catch (e) { fail(e) } finally { loading.value = false } }
async function more(kind: 'jd' | 'sprint') { try { const path = kind === 'jd' ? '/jd-diagnostics' : '/sprints', c = kind === 'jd' ? diagnosticCursor.value : sprintCursor.value; const p = await v2<Page<Row>>(`${path}?limit=20&cursor=${encodeURIComponent(c || '')}`); if (kind === 'jd') { diagnostics.value.push(...p.items); diagnosticCursor.value = p.nextCursor } else { sprints.value.push(...p.items); sprintCursor.value = p.nextCursor } } catch (e) { fail(e) } }
async function prepare() { busy.value = true; error.value = ''; try { manifest.value = await writeV2<Manifest>('/jd-diagnostics/input-preparations', { ...(jdMaterialIds.value[0] ? { jdMaterialId: jdMaterialIds.value[0] } : { jdText: jdText.value }), materialIds: materialIds.value, trainingEventIds: observationIds.value }) } catch (e) { fail(e) } finally { busy.value = false } }
async function generate() { if (!manifest.value) return; busy.value = true; error.value = ''; try { const d = await writeV2<Row>('/jd-diagnostics', { manifestId: manifest.value.manifestId, manifestHash: manifest.value.manifestHash, ...(replaceOf.value ? { replaceOf: replaceOf.value } : {}) }); await router.push(`/jd-diagnostics/${d.id}`) } catch (e) { fail(e) } finally { busy.value = false } }
async function confirm() { if (!diagnostic.value) return; busy.value = true; try { diagnostic.value = await writeV2(`/jd-diagnostics/${id.value}/confirm`, { expectedVersion: diagnostic.value.revision, requirementIds: selected.value, importanceUpdates: importance }); message.value = '所选要求与重要性已由你确认，可以创建短清单。' } catch (e) { fail(e) } finally { busy.value = false } }
async function createSprint() { if (!diagnostic.value) return; busy.value = true; try { const s = await writeV2<Row>('/sprints', { confirmedDiagnosticId: id.value, actions: selected.value.map(rid => ({ requirementId: rid, type: actionTypes[rid], purpose: purposes[rid], completionCondition: conditions[rid] })) }); await router.push(`/sprints/${s.id}`) } catch (e) { fail(e) } finally { busy.value = false } }
async function revision() { if (diagnostic.value) await router.push({ path: '/jd-diagnostics', query: { replaceOf: diagnostic.value.id } }) }
async function sprintAction(action: string, extra: Row = {}) { if (!sprint.value) return; busy.value = true; error.value = ''; try { await writeV2(`/sprints/${id.value}/actions`, { expectedVersion: sprint.value.revision, action, ...extra }); sprint.value = await v2(`/sprints/${id.value}`); message.value = '行动变更已保存，完成记录只代表本次用户确认。' } catch (e) { fail(e) } finally { busy.value = false } }
async function practice(a: Row) { busy.value = true; try { const link = await writeV2<Row>('/training-links', { sourceKind: 'JD', sourceId: a.sourceDiagnosticId || sprint.value!.diagnosticId, requirementIds: [a.requirementId], sprintId: id.value, actionId: a.id }); await router.push({ path: '/configure/quick', query: { trainingLinkId: link.id, focus: a.purpose } }) } catch (e) { fail(e) } finally { busy.value = false } }
async function readReport() { try { const link = await v2<Row>(`/training-links/${linkId.value}`); if (!link.sessionId) throw new Error('尚未开始这次训练'); report.value = await v2<Row>(`/api/sessions/${link.sessionId}/report`) } catch (e) { fail(e) } }
function reportOptions() { const out: { value: string; label: string; index: number; kind: string; text: string }[] = []; for (const q of report.value?.questions || []) for (const kind of ['correct', 'incorrect', 'missing', 'uncertain']) for (const text of q[kind] || []) out.push({ value: `${out.length}`, label: `第 ${q.questionIndex + 1} 题 · ${text}`, index: q.questionIndex, kind, text }); return out }
async function previewCompletion() { try { const a = sprint.value!.actions.find((x: Row) => x.id === completionAction.value); completionPreview.value = await v2(`/jd-diagnostics/${a.sourceDiagnosticId || sprint.value!.diagnosticId}/completion-material?materialId=${encodeURIComponent(completionMaterialId.value[0] || '')}`) } catch (e) { fail(e) } }
async function complete() { const a = sprint.value?.actions.find((x: Row) => x.id === completionAction.value); if (!a) return; let evidence: Row; if (a.type === 'MATERIAL_UPDATE') evidence = { materialId: completionPreview.value?.id, materialHash: completionPreview.value?.hash }; else { const option = reportOptions().find(o => o.value === reportSelection.value); if (!option) return; evidence = { trainingLinkId: linkId.value, evidenceQuestionIndex: option.index, reportKind: option.kind, reportText: option.text, reason: completionReason.value } } await sprintAction('COMPLETE', { actionId: a.id, coverageConfirmed: coverage.value, ...evidence }) }
function canReorder(index: number, direction: number) { const actions = sprint.value?.actions; const other = index + direction; return !busy.value && !!actions && other >= 0 && other < actions.length && actions[index]?.priority === actions[other]?.priority }
async function reorder(index: number, direction: number) { if (!canReorder(index, direction)) return; const ids = sprint.value!.actions.map((a: Row) => a.id); const other = index + direction; [ids[index], ids[other]] = [ids[other], ids[index]]; await sprintAction('REORDER', { actionIds: ids }) }
async function previewDiff() { try { diff.value = await v2(`/sprints/${id.value}/diagnostic-diff?diagnosticId=${encodeURIComponent(newerId.value)}`) } catch (e) { fail(e) } }
async function loadHistory(more = false) { try { const p = await v2<Page<Row>>(`/sprints/${id.value}/history?limit=20&cursor=${encodeURIComponent(more ? historyCursor.value || '' : '')}`); history.value = more ? [...history.value, ...p.items] : p.items; historyCursor.value = p.nextCursor } catch (e) { fail(e) } }
async function restoreRevisionSource() { if (!replaceOf.value || id.value) return; try { const old = await v2<Row>(`/jd-diagnostics/${replaceOf.value}`); jdText.value = old.manifest.modelInput.jdText; const jdIdentity = old.manifest.modelInput.jdSourceIdentity; jdMaterialIds.value = jdIdentity && jdIdentity !== 'MANUAL' ? [jdIdentity] : []; materialIds.value = [...new Set<string>(old.manifest.snapshots.filter((s: Row) => s.purpose === 'MATERIAL' && s.materialId).map((s: Row) => s.materialId))].slice(0, 5); observationIds.value = []; manifest.value = null } catch (e) { fail(e) } }
watch([jdText, jdMaterialIds, materialIds, observationIds], () => { manifest.value = null }, { deep: true })
onMounted(async () => { replaceOf.value = String(route.query.replaceOf || ''); await load(); await restoreRevisionSource() })
</script>
<template><div class="page v2-page"><div class="page-heading"><h1>{{ isSprint ? '把差距，落到几件具体行动。' : '对照岗位要求，找到下一步。' }}</h1><p>材料提及、训练证据和用户确认分别展示，不推算录用概率。</p></div><Notice :message="error" kind="error" /><Notice :message="message" /><ModelRecovery :error="recovery" @recovered="load()" /><LoadingState v-if="loading" label="正在读取岗位训练记录…" />
<template v-if="!id && !loading"><form class="panel v2-form" @submit.prevent="prepare"><h2>{{ replaceOf ? '生成新版诊断（旧版保留）' : '先预览发送范围' }}</h2><div><label for="jd-input">岗位描述 JD</label><textarea id="jd-input" v-model="jdText" maxlength="10000" rows="7" placeholder="粘贴岗位原文。最多整理 12 条要求，过多时请先缩小范围。" /></div><details><summary>也可使用已保存的 JD</summary><MaterialPicker v-model="jdMaterialIds" :kinds="['JD']" /><p class="tiny muted">选择后使用第一份 JD，文本框内容仍保留。</p></details><MaterialPicker v-model="materialIds" /><fieldset class="v2-fieldset"><legend>已确认训练观察（可选，最多 20 条）</legend><p v-if="!observations.length" class="muted">本页暂无可接受观察；没有训练证据时明确显示尚未验证。</p><div class="v2-checks"><label v-for="o in observations" :key="o.id"><input v-model="observationIds" type="checkbox" :value="o.id" :disabled="!observationIds.includes(o.id) && observationIds.length >= 20" />{{ o.texts.join('；') }}{{ o.mock ? ' · Mock' : '' }}</label></div><button v-if="observationCursor" type="button" class="text-link" @click="loadObservations(true)">继续读取观察</button></fieldset><button class="btn btn-primary" data-action="prepare-jd" :disabled="busy || (!jdText.trim() && !jdMaterialIds.length)">预览本次模型输入（不调用模型）</button><InputPreview v-if="manifest" :manifest="manifest" /><button v-if="manifest" type="button" class="btn btn-primary" :disabled="busy" @click="generate">确认发送上述快照并调用模型生成诊断</button></form>
<section class="panel v2-section"><h2>历史诊断</h2><p v-if="!diagnostics.length" class="muted">还没有诊断。所有确认和新版都会保留来源快照。</p><article v-for="d in diagnostics" :key="d.id" class="v2-list-row"><div><h3>诊断版本 {{ d.diagnosticVersion }}</h3><p>{{ statusLabels[d.status] }} · {{ localDate(d.createdAt) }}{{ d.mock ? ' · Mock' : '' }}{{ d.sourcesChanged ? ' · 来源有变化' : '' }}</p></div><RouterLink :to="`/jd-diagnostics/${d.id}`" class="btn btn-secondary">查看要求与证据</RouterLink></article><button v-if="diagnosticCursor" class="text-link" @click="more('jd')">加载更多诊断</button></section><section class="panel v2-section"><h2>短冲刺清单</h2><p v-if="!sprints.length" class="muted">确认诊断要求后，选择最多 5 件具体行动建立清单。</p><article v-for="s in sprints" :key="s.id" class="v2-list-row"><div><h3>7 天参考清单</h3><p>{{ statusLabels[s.status] }} · {{ localDate(s.createdAt) }}</p></div><RouterLink :to="`/sprints/${s.id}`" class="btn btn-secondary">查看清单</RouterLink></article><button v-if="sprintCursor" class="text-link" @click="more('sprint')">加载更多清单</button></section></template>
<template v-if="diagnostic"><section class="panel v2-flow"><div class="v2-toolbar"><span class="badge badge-gray">诊断版本 {{ diagnostic.diagnosticVersion }} · {{ statusLabels[diagnostic.status] }}</span><span v-if="diagnostic.mock" class="badge badge-orange">Mock · 流程数据</span><RouterLink to="/jd-diagnostics" class="text-link">返回列表</RouterLink></div><p v-if="diagnostic.sourcesChanged" class="notice">来源已变化或有争议。生成时判词保留；当前训练状态重新核对。请显式发起新版诊断。</p><p>{{ diagnostic.coverageNotice }}</p><InputPreview :manifest="diagnostic.manifest" /><article v-for="r in diagnostic.requirements" :key="r.id" class="v2-finding"><label class="v2-inline-check"><input v-model="selected" type="checkbox" :value="r.id" :disabled="diagnostic.status !== 'READY' && !r.confirmed" />{{ r.jdQuote }}</label><div class="v2-evidence-columns"><section><h3>JD 要求</h3><p>原文：{{ r.jdEvidence.quote }}</p><label :for="`importance-${r.id}`">重要性（用户确认）</label><select :id="`importance-${r.id}`" v-model="importance[r.id]" :disabled="diagnostic.status !== 'READY'"><option value="REQUIRED">岗位必需</option><option value="PREFERRED">加分项</option><option value="UNSPECIFIED">未明确</option></select><p class="tiny muted">模型建议依据：{{ r.priorityReason }}</p></section><section><h3>材料证据</h3><p>{{ r.materialProvided === false ? '未提供材料' : materialLabels[r.materialCoverage] }}</p><p v-for="(ref, i) in r.evidenceRefs" :key="i" class="tiny muted">{{ ref.kind === 'QUOTE' ? `材料原文：${ref.quote}` : `已检查快照全文，范围 ${ref.start}–${ref.end}` }}</p></section><section><h3>训练证据</h3><p>{{ trainingLabels[r.currentTrainingStatus || r.trainingStatus] }}</p><p class="tiny muted">生成时：{{ trainingLabels[r.trainingStatus] }}。局部支持不代表岗位整体掌握。</p><RouterLink v-for="binding in r.trainingBindings" :key="binding.eventId + binding.findingId" :to="`/skills`" class="text-link">核对训练观察与来源</RouterLink></section></div><template v-if="diagnostic.status === 'CONFIRMED' && r.confirmed && selected.includes(r.id)"><div class="v2-form"><label :for="`type-${r.id}`">行动类型</label><select :id="`type-${r.id}`" v-model="actionTypes[r.id]"><option v-for="(label, key) in typeLabels" :key="key" :value="key">{{ label }}</option></select><label :for="`purpose-${r.id}`">具体目的</label><input :id="`purpose-${r.id}`" v-model="purposes[r.id]" maxlength="1000" /><label :for="`condition-${r.id}`">完成条件</label><input :id="`condition-${r.id}`" v-model="conditions[r.id]" maxlength="1000" /></div></template></article><button v-if="diagnostic.status === 'READY'" class="btn btn-primary" :disabled="busy || !selected.length" @click="confirm">确认所选要求与重要性</button><template v-if="diagnostic.status === 'CONFIRMED'"><p class="tiny muted">当前选 {{ selected.length }} 项；清单活动项最多 5 个。7 天为参考窗口。</p><button class="btn btn-primary" :disabled="busy || !selected.length || selected.length > 5" @click="createSprint">按所选行动创建短清单</button></template><button class="text-link" :disabled="busy" @click="revision">按当前资料生成新版诊断</button></section></template>
<template v-if="sprint"><section class="panel v2-flow"><div class="v2-toolbar"><h2>7 天参考清单</h2><span class="badge badge-gray">{{ statusLabels[sprint.status] }}</span><RouterLink :to="`/jd-diagnostics/${sprint.diagnosticId}`" class="text-link">查看当前诊断</RouterLink></div><p>{{ sprint.windowNotice }}</p><p v-if="sprint.sourcesChanged" class="notice">来源已变化。旧完成记录保留；新确认和完成会重新检查来源。</p><article v-for="(a, actionIndex) in sprint.actions" :key="a.id" class="v2-finding"><span class="badge badge-gray">{{ statusLabels[a.status] }}{{ a.obsolete ? ' · 旧要求已失效' : '' }}</span><h3>{{ a.purpose }}</h3><p>{{ typeLabels[a.type] }} · {{ a.requirementSnapshot?.jdQuote }}</p><p class="tiny muted">完成条件：{{ a.completionCondition }}<br />优先级依据：{{ a.priorityReason }}<br />当前训练：{{ trainingLabels[a.currentTrainingStatus] }}</p><RouterLink :to="`/jd-diagnostics/${a.sourceDiagnosticId || sprint.diagnosticId}`" class="text-link">核对行动原诊断</RouterLink><div v-if="!a.obsolete && sprint.status === 'ACTIVE'" class="v2-action-row"><button class="text-link" :disabled="!canReorder(Number(actionIndex), -1)" @click="reorder(Number(actionIndex), -1)">上移</button><button class="text-link" :disabled="!canReorder(Number(actionIndex), 1)" @click="reorder(Number(actionIndex), 1)">下移</button><button v-if="a.status === 'TODO'" class="btn btn-secondary" :disabled="busy" @click="sprintAction('START', { actionId: a.id })">开始行动</button><button v-if="['TODO', 'IN_PROGRESS'].includes(a.status) && a.type !== 'MATERIAL_UPDATE'" class="btn btn-primary" :disabled="busy" @click="practice(a)">进入关联专项练习</button><RouterLink v-if="a.type === 'MATERIAL_UPDATE'" to="/materials" class="text-link">前往资料库补充</RouterLink><button v-if="['TODO', 'IN_PROGRESS'].includes(a.status)" class="btn btn-secondary" :disabled="busy" @click="completionAction = a.id; coverage = false; completionPreview = null">选择依据并确认完成</button><button v-if="['DONE', 'SKIPPED'].includes(a.status)" class="btn btn-secondary" :disabled="busy" @click="sprintAction('REOPEN', { actionId: a.id })">重新安排</button></div><details v-if="['TODO', 'IN_PROGRESS'].includes(a.status)"><summary>跳过并保留原因</summary><label :for="`skip-${a.id}`">跳过原因</label><input :id="`skip-${a.id}`" v-model="skipReasons[a.id]" maxlength="1000" /><button class="btn btn-secondary" :disabled="busy || !skipReasons[a.id]?.trim()" @click="sprintAction('SKIP', { actionId: a.id, reason: skipReasons[a.id] })">确认跳过</button></details><details v-if="a.completionEvidence"><summary>查看当时完成依据</summary><p>{{ a.completionEvidence.reportText || '用户确认了修订后的材料快照' }}</p><p>{{ a.completionEvidence.reason }}</p><div v-for="snapshot in a.completionEvidence.materialSnapshot?.snapshots" :key="snapshot.id"><pre>{{ snapshot.text }}</pre></div><p class="tiny muted">确认时间：{{ localDate(a.completionEvidence.confirmedAt) }}。这是用户确认记录，不是岗位能力证明。</p></details></article>
<section v-if="completionAction" class="v2-form v2-preview"><h2>确认行动完成依据</h2><template v-if="sprint.actions.find((a: Row) => a.id === completionAction)?.type === 'MATERIAL_UPDATE'"><MaterialPicker v-model="completionMaterialId" /><button class="btn btn-secondary" :disabled="busy || !completionMaterialId.length" @click="previewCompletion">预览第一份所选材料的修订版本</button><div v-if="completionPreview"><h3>{{ completionPreview.name }}</h3><pre v-for="s in completionPreview.snapshots" :key="s.id">{{ s.text }}</pre></div></template><template v-else><label for="completion-link">训练来源 ID（报告返回时自动带入）</label><input id="completion-link" v-model="linkId" /><button class="btn btn-secondary" :disabled="busy || !linkId.trim()" @click="readReport">读取已完成训练报告</button><label for="completion-report">实际覆盖此要求的报告结论</label><select id="completion-report" v-model="reportSelection"><option value="">请选择具体题目及结论</option><option v-for="o in reportOptions()" :key="o.value" :value="o.value">{{ o.label }}</option></select><label for="completion-reason">为何覆盖这个要求</label><textarea id="completion-reason" v-model="completionReason" maxlength="1000" /></template><label class="v2-inline-check"><input v-model="coverage" type="checkbox" />我已核对，这份资料或训练确实覆盖该要求</label><button class="btn btn-primary" :disabled="busy || !coverage" @click="complete">确认本次行动完成</button></section>
<details @toggle="($event.target as HTMLDetailsElement).open && loadHistory()"><summary>查看完整操作历史</summary><div v-for="h in history" :key="h.id" class="v2-quote"><button class="text-link" @click="v2<Row>(`/sprints/${id}/history/${h.id}`).then(r => historical = r).catch(fail)">查看 {{ localDate(h.createdAt) }} 的清单快照</button></div><button v-if="historyCursor" class="text-link" @click="loadHistory(true)">读取更多历史</button><div v-if="historical"><h3>历史行动快照</h3><p v-for="a in historical.actions" :key="a.id">{{ a.purpose }} · {{ statusLabels[a.status] }} · {{ a.requirementSnapshot?.jdQuote }} · {{ a.completionEvidence?.reportText }}</p></div></details><details v-if="sprint.status === 'ACTIVE'"><summary>查看并确认应用新版诊断</summary><p class="tiny muted">新版须为同一诊断族中已确认的较新版本。不会按近似文字偷偷合并要求。</p><label for="new-diagnostic">新版诊断 ID</label><input id="new-diagnostic" v-model="newerId" /><button class="btn btn-secondary" :disabled="busy || !newerId" @click="previewDiff">先查看更新差异</button><div v-if="diff"><p>保留 {{ diff.kept.length }} 项，失效 {{ diff.obsolete.length }} 项，已完成 {{ diff.completed.length }} 项；完成证据保留。</p><button class="btn btn-primary" :disabled="busy" @click="sprintAction('APPLY_DIAGNOSTIC', { diagnosticId: newerId, diffHash: diff!.diffHash, confirmDifferences: true })">确认上述差异并应用新版</button><p class="tiny muted">新增行动可从新版诊断另建清单，旧行动和原诊断仍可回看。</p></div></details><button v-if="sprint.status === 'ACTIVE'" class="btn btn-ghost" :disabled="busy" @click="sprintAction('ARCHIVE')">归档清单并保留历史</button></section></template></div></template>
